tool_calls:
cat > /tmp/merge_ini.awk << 'EOF'
# Merge INI files: later files override earlier ones per-section.
# Preserves section order and key order (first occurrence); overridden
# keys keep their original position, new keys append to their section.
BEGIN { sec = "" }
/^[[:space:]]*\[/ {
    sec = $0
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", sec)
    if (!(sec in seen_sec)) {
        seen_sec[sec] = 1
        sec_order[++nsec] = sec
    }
    next
{
    line = $0
    if (line ~ /^[[:space:]]*$/ || line ~ /^[[:space:]]*[;#]/) next
    key = line
    sub(/=.*/, "", key)
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", key)
    id = sec SUBSEP key
    if (!(id in seen_key)) {
        seen_key[id] = 1
        key_order[sec, ++keycnt[sec]] = key
    }
    val[id] = line
}
END {
    for (i = 1; i <= nsec; i++) {
        s = sec_order[i]
        print s
        for (j = 1; j <= keycnt[s]; j++) {
            k = key_order[s, j]
            print val[s SUBSEP k]
        }
        if (i < nsec) print ""
    }
}
EOF
awk -f /tmp/merge_ini.awk /config/defaults.ini /config/custom.ini > /config/merged.ini
cat /config/merged.ini

